async function hhPgLoad(force){
  if(_hhPg.loaded && !force) return _hhPg.list;
  var list=[];
  try{
    var qs=await _hhPgDb().collection('custom_programs').get();
    qs.forEach(function(d){ var p=d.data()||{}; p.id=d.id; list.push(p); });
    try{ localStorage.setItem('hh_custom_programs', JSON.stringify(list)); }catch(e){}
  }catch(e){
    try{ list=JSON.parse(localStorage.getItem('hh_custom_programs')||'[]')||[]; }catch(_e){ list=[]; }
  }
  // zzzzzzac · برنامج المتحدث المُلهم مضمّن افتراضياً · يظهر تلقائياً، ويُستبدل بنسختك متى عدّلته وحفظته
  try{ var _spDef = {"id":"prog_speaker_default","type":"program","status":"done","name":"المتحدث المُلهم","desc":"برنامج في فنّ الإلقاء والحضور لطلاب المرحلة الإعدادية، يُدرّبهم على مواجهة الجمهور والتحدث بثقة أمام الحضور، ويُختتم بحفل تكريم وشهادات معتمدة.","features":"تدريب عملي على الوقوف أمام الجمهور\nمحطات متدرجة في مهارات الإلقاء\nحفل ختامي وتكريم للمتحدثين","goals":"بناء ثقة الطالب في التحدث أمام الآخرين\nتنمية مهارات العرض والإقناع\nاكتشاف المواهب الخطابية ورعايتها","achievements":"تدرّب أكثر من 28 طالباً على الإلقاء أمام الجمهور\nحفل ختامي وتكريم بشهادات معتمدة\nارتفاع ملحوظ في ثقة الطلاب ومهارات العرض","place":"قاعة المدرسة","audience":"الطلاب","ages":"المرحلة الإعدادية","price":"","seats":0,"regMode":"internal","regLink":"","img":"data:image/jpeg;base64,","gallery":["data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,","data:image/jpeg;base64,"],"hidden":false,"confirmedCount":0,"isDefault":true,"updatedAt":0,"createdAt":0};
    if(!list.some(function(p){ return p.id===_spDef.id || p.name===_spDef.name; })){ list.push(_spDef); }
  }catch(_e){}
  list.sort(function(a,b){ return String(a.dateFrom||'9999').localeCompare(String(b.dateFrom||'9999')) || (b.updatedAt||0)-(a.updatedAt||0); });
  _hhPg.list=list; _hhPg.loaded=true; return list;
}
